class Solution {
public:
    int numberOfRounds(string loginTime, string logoutTime) {
        int lh = (loginTime[0] - '0') * 10 + (loginTime[1] - '0');
        int lm = (loginTime[3] - '0') * 10 + (loginTime[4] - '0');
        int rh = (logoutTime[0] - '0') * 10 + (logoutTime[1] - '0');
        int rm = (logoutTime[3] - '0') * 10 + (logoutTime[4] - '0');
        int login = lh * 60 + lm;
        int logout = rh * 60 + rm;
        if (logout <= login) logout += 1440;
        int smallest = ((login + 14) / 15) * 15;
        int largest = ((logout - 15) / 15) * 15;
        if (smallest > largest) return 0;
        return (largest - smallest) / 15 + 1;
    }
};
